from enum import Enum
from typing import Callable

class FallbackStrategy(Enum):
    RETRY = "retry"
    USE_CACHE = "use_cache"
    USE_DEFAULT = "use_default"
    SKIP_STEP = "skip_step"
    ABORT_CHAIN = "abort_chain"
    ESCALATE_HUMAN = "escalate_human"

class ResilientToolChain:
    """Tool chain with fallback strategies per tool."""

    def __init__(self):
        self.fallbacks: dict[str, tuple[FallbackStrategy, any]] = {}
        self.cache: dict[str, str] = {}

    def register_fallback(self, tool_name: str, strategy: FallbackStrategy, fallback_value: any = None):
        self.fallbacks[tool_name] = (strategy, fallback_value)

    def execute_with_fallback(self, tool_name: str, executor: Callable, **kwargs) -> tuple[str, bool]:
        """
        Execute tool with fallback. Returns (result, is_fallback).
        """
        try:
            result = executor(**kwargs)
            if result is None or (isinstance(result, str) and not result.strip()):
                raise ValueError(f"Tool '{tool_name}' returned empty result")
            # Cache successful results
            cache_key = f"{tool_name}:{str(sorted(kwargs.items()))}"
            self.cache[cache_key] = str(result)
            return str(result), False

        except Exception as e:
            logger.warning(f"Tool '{tool_name}' failed: {e}. Applying fallback.")
            strategy, fallback_value = self.fallbacks.get(tool_name, (FallbackStrategy.ABORT_CHAIN, None))

            if strategy == FallbackStrategy.USE_CACHE:
                cache_key = f"{tool_name}:{str(sorted(kwargs.items()))}"
                cached = self.cache.get(cache_key)
                if cached:
                    logger.info(f"Using cached result for '{tool_name}'")
                    return f"[CACHED] {cached}", True
                return f"ERROR: No cache available for '{tool_name}'", True

            elif strategy == FallbackStrategy.USE_DEFAULT:
                return str(fallback_value), True

            elif strategy == FallbackStrategy.SKIP_STEP:
                return f"SKIPPED: '{tool_name}' unavailable. Proceeding without this data.", True

            elif strategy == FallbackStrategy.ABORT_CHAIN:
                raise RuntimeError(f"Critical tool '{tool_name}' failed, aborting chain: {e}")

            elif strategy == FallbackStrategy.ESCALATE_HUMAN:
                return f"HUMAN_ESCALATION_REQUIRED: '{tool_name}' failed. Please assist.", True

            return f"ERROR: {e}", True
